2511	static int x509_crt_verify_chain(
2512	    mbedtls_x509_crt *crt,
2513	    mbedtls_x509_crt *trust_ca,
2514	    mbedtls_x509_crl *ca_crl,
2515	    mbedtls_x509_crt_ca_cb_t f_ca_cb,
2516	    void *p_ca_cb,
2517	    const mbedtls_x509_crt_profile *profile,
2518	    mbedtls_x509_crt_verify_chain *ver_chain,
2519	    mbedtls_x509_crt_restart_ctx *rs_ctx)
2520	{
2521	    /* Don't initialize any of those variables here, so that the compiler can
2522	     * catch potential issues with jumping ahead when restarting */
2523	    int ret = MBEDTLS_ERR_ERROR_CORRUPTION_DETECTED;
2524	    uint32_t *flags;
2525	    mbedtls_x509_crt_verify_chain_item *cur;
2526	    mbedtls_x509_crt *child;
2527	    mbedtls_x509_crt *parent;
2528	    int parent_is_trusted;
2529	    int child_is_trusted;
2530	    int signature_is_good;
2531	    unsigned self_cnt;
2532	    mbedtls_x509_crt *cur_trust_ca = NULL;
2533	    mbedtls_x509_time now;
2534	
2535	#if defined(MBEDTLS_HAVE_TIME_DATE)
2536	    if (mbedtls_x509_time_gmtime(mbedtls_time(NULL), &now) != 0) {
2537	        return MBEDTLS_ERR_X509_FATAL_ERROR;
2538	    }
2539	#endif
2540	
2541	#if defined(MBEDTLS_ECDSA_C) && defined(MBEDTLS_ECP_RESTARTABLE)
2542	    /* resume if we had an operation in progress */
2543	    if (rs_ctx != NULL && rs_ctx->in_progress == x509_crt_rs_find_parent) {
2544	        /* restore saved state */
2545	        *ver_chain = rs_ctx->ver_chain; /* struct copy */
2546	        self_cnt = rs_ctx->self_cnt;
2547	
2548	        /* restore derived state */
2549	        cur = &ver_chain->items[ver_chain->len - 1];
2550	        child = cur->crt;
2551	        flags = &cur->flags;
2552	
2553	        goto find_parent;
2554	    }
2555	#endif /* MBEDTLS_ECDSA_C && MBEDTLS_ECP_RESTARTABLE */
2556	
2557	    child = crt;
2558	    self_cnt = 0;
2559	    parent_is_trusted = 0;
2560	    child_is_trusted = 0;
2561	
2562	    while (1) {
2563	        /* Add certificate to the verification chain */
2564	        cur = &ver_chain->items[ver_chain->len];
2565	        cur->crt = child;
2566	        cur->flags = 0;
2567	        ver_chain->len++;
2568	        flags = &cur->flags;
2569	
2570	#if defined(MBEDTLS_HAVE_TIME_DATE)
2571	        /* Check time-validity (all certificates) */
2572	        if (mbedtls_x509_time_cmp(&child->valid_to, &now) < 0) {
2573	            *flags |= MBEDTLS_X509_BADCERT_EXPIRED;
2574	        }
2575	
2576	        if (mbedtls_x509_time_cmp(&child->valid_from, &now) > 0) {
2577	            *flags |= MBEDTLS_X509_BADCERT_FUTURE;
2578	        }
2579	#endif
2580	
2581	        /* Stop here for trusted roots (but not for trusted EE certs) */
2582	        if (child_is_trusted) {
2583	            return 0;
2584	        }
2585	
2586	        /* Check signature algorithm: MD & PK algs */
2587	        if (mbedtls_x509_profile_check_md_alg(profile, child->sig_md) != 0) {
2588	            *flags |= MBEDTLS_X509_BADCERT_BAD_MD;
2589	        }
2590	
2591	        if (mbedtls_x509_profile_check_pk_alg(profile, child->sig_pk) != 0) {
2592	            *flags |= MBEDTLS_X509_BADCERT_BAD_PK;
2593	        }
2594	
2595	        /* Special case: EE certs that are locally trusted */
2596	        if (ver_chain->len == 1 &&
2597	            x509_crt_check_ee_locally_trusted(child, trust_ca) == 0) {
2598	            return 0;
2599	        }
2600	
2601	#if defined(MBEDTLS_ECDSA_C) && defined(MBEDTLS_ECP_RESTARTABLE)
2602	find_parent:
2603	#endif
2604	
2605	        /* Obtain list of potential trusted signers from CA callback,
2606	         * or use statically provided list. */
2607	#if defined(MBEDTLS_X509_TRUSTED_CERTIFICATE_CALLBACK)
2608	        if (f_ca_cb != NULL) {
2609	            mbedtls_x509_crt_free(ver_chain->trust_ca_cb_result);
2610	            mbedtls_free(ver_chain->trust_ca_cb_result);
2611	            ver_chain->trust_ca_cb_result = NULL;
2612	
2613	            ret = f_ca_cb(p_ca_cb, child, &ver_chain->trust_ca_cb_result);
2614	            if (ret != 0) {
2615	                return MBEDTLS_ERR_X509_FATAL_ERROR;
2616	            }
2617	
2618	            cur_trust_ca = ver_chain->trust_ca_cb_result;
2619	        } else
2620	#endif /* MBEDTLS_X509_TRUSTED_CERTIFICATE_CALLBACK */
2621	        {
2622	            ((void) f_ca_cb);
2623	            ((void) p_ca_cb);
2624	            cur_trust_ca = trust_ca;
2625	        }
2626	
2627	        /* Look for a parent in trusted CAs or up the chain */
2628	        ret = x509_crt_find_parent(child, cur_trust_ca, &parent,
2629	                                   &parent_is_trusted, &signature_is_good,
2630	                                   ver_chain->len - 1, self_cnt, rs_ctx,
2631	                                   &now);
2632	
2633	#if defined(MBEDTLS_ECDSA_C) && defined(MBEDTLS_ECP_RESTARTABLE)
2634	        if (rs_ctx != NULL && ret == MBEDTLS_ERR_ECP_IN_PROGRESS) {
2635	            /* save state */
2636	            rs_ctx->in_progress = x509_crt_rs_find_parent;
2637	            rs_ctx->self_cnt = self_cnt;
2638	            rs_ctx->ver_chain = *ver_chain; /* struct copy */
2639	
2640	            return ret;
2641	        }
2642	#else
2643	        (void) ret;
2644	#endif
2645	
2646	        /* No parent? We're done here */
2647	        if (parent == NULL) {
2648	            *flags |= MBEDTLS_X509_BADCERT_NOT_TRUSTED;
2649	            return 0;
2650	        }
2651	
2652	        /* Count intermediate self-issued (not necessarily self-signed) certs.
2653	         * These can occur with some strategies for key rollover, see [SIRO],
2654	         * and should be excluded from max_pathlen checks. */
2655	        if (ver_chain->len != 1 &&
2656	            x509_name_cmp(&child->issuer, &child->subject) == 0) {
2657	            self_cnt++;
2658	        }
2659	
2660	        /* path_cnt is 0 for the first intermediate CA,
2661	         * and if parent is trusted it's not an intermediate CA */
2662	        if (!parent_is_trusted &&
2663	            ver_chain->len > MBEDTLS_X509_MAX_INTERMEDIATE_CA) {
2664	            /* return immediately to avoid overflow the chain array */
2665	            return MBEDTLS_ERR_X509_FATAL_ERROR;
2666	        }
2667	
2668	        /* signature was checked while searching parent */
2669	        if (!signature_is_good) {
2670	            *flags |= MBEDTLS_X509_BADCERT_NOT_TRUSTED;
2671	        }
2672	
2673	        /* check size of signing key */
2674	        if (x509_profile_check_key(profile, &parent->pk) != 0) {
2675	            *flags |= MBEDTLS_X509_BADCERT_BAD_KEY;
2676	        }
2677	
2678	#if defined(MBEDTLS_X509_CRL_PARSE_C)
2679	        /* Check trusted CA's CRL for the given crt */
2680	        *flags |= x509_crt_verifycrl(child, parent, ca_crl, profile, &now);
2681	#else
2682	        (void) ca_crl;
2683	#endif
2684	
2685	        /* prepare for next iteration */
2686	        child = parent;
2687	        parent = NULL;
2688	        child_is_trusted = parent_is_trusted;
2689	        signature_is_good = 0;
2690	    }
2691	}
